# -*- coding: utf-8 -*-
"""Код обмена и ссылка на бота: по ней сдают фото и видео сделки.

Как это выглядит на точке:

  1. Приложение придумывает короткий код и показывает ссылку с ним:
     `https://t.me/<бот>?start=p7KQ2M` (и QR на неё).
  2. Сотрудник открывает ссылку своим телефоном — бот сразу знает, КТО пришёл, по
     chat_id находит его в `users`. Это и есть оценщик сделки: отдельно спрашивать
     «кто проводил оценку» не нужно.
  3. Сотрудник шлёт боту видео и фото, бот складывает `file_id` в строку с этим кодом.
  4. Сделку с тем же кодом бот создаёт сам (ocenka_tg.py отдаёт ему посылку) и подставляет
     в неё это видео и эти фото.

Почему так: Оценка хранит медиа не файлами, а `file_id` Telegram — значит хранение
бесплатное и ничего своего поднимать не нужно. А главное, видео обязательно: без него
Оценка не открывает карточку сделки.

Код здесь только придумывается — в базу его пишет бот, когда сотрудник открывает ссылку.
С точки в базу Оценки хода нет: порт Postgres закрыт наружу.
"""
from __future__ import annotations

import secrets

# Код диктуют голосом и набирают руками, поэтому ни одной пары, которую легко спутать:
# нет O и 0, I и 1, B и 8, S и 5, Z и 2.
АЛФАВИТ = "ACDEFGHJKLMNPQRTUVWXY345679"


def новый_код(n: int = 6) -> str:
    return "".join(secrets.choice(АЛФАВИТ) for _ in range(n))


def ссылка(бот: str, код: str) -> str:
    """Готовая ссылка с командой: открывший её сразу попадает на нужную сделку."""
    бот = str(бот or "").strip().lstrip("@").removeprefix("https://t.me/").strip("/")
    return f"https://t.me/{бот}?start=p{код}"


# ---------------------------------------------------------------- ручная диагностика

# Пункты, которые сотрудник отмечает РУКАМИ в боте, последним шагом сделки. Здесь только то,
# чего не может ни кабель (он читает прошивку и привязку модулей), ни страница теста на
# телефоне клиента (браузер не нажмёт кнопку, не включит вибрацию и не посмотрит в лоток SIM).
# Экран, касание, камеры, динамик и микрофон прогоняет сам телефон — см. pintel_core.phonetest.
#
# КОПИЯ списка из `deploy/оценка_бот/kiosk_core.py` (ПУНКТЫ): там его спрашивает бот, здесь
# показывает программа на точке, а живут они в разных местах — бот на сервере, программа в
# exe. Расхождение сверяется тестом test_ocenka_tg.py, как и префикс кнопки сделки.
ПУНКТЫ = (
    ("keys", "Кнопки", "питание, громкость, бесшумный режим"),
    ("vibro", "Вибрация", "Taptic отзывается (в браузере это не проверить)"),
    ("bio", "Face ID", "разблокировка лицом или отпечатком"),
    ("charge", "Зарядка", "заряжается от кабеля"),
    ("net", "Связь", "SIM видна, сеть и Wi-Fi работают"),
    ("water", "Влага", "в лотке SIM нет следов воды"),
    ("apple", "Детали Apple", "Об этом устройстве → Детали и обслуживание: неизвестных деталей нет"),
    ("mdm", "Управление", "VPN и управление устройством: чужих профилей нет"),
)


КЛЮЧИ = tuple(k for k, _, _ in ПУНКТЫ)
ЗАПЕЧАТАН = "sealed"                   # коробку не вскрывали — проверять нечего

# Сколько фото ждёт бот: экран с *#06#, лицевая, задняя (kiosk_core.ЭТАПЫ_ФОТО). Это нужно
# знать и здесь: программа на точке показывает, сколько уже дошло, и не даёт отправить
# сделку, пока медиа не собраны. Расхождение со списком бота ловит тест.
НУЖНО_ФОТО = 3


def пункты_словами(разделитель: str = " · ") -> str:
    """Короткие надписи пунктов — для экрана программы: сотрудник видит, что его ждёт, и
    проверяет телефон, пока он в руках."""
    return разделитель.join(к for _, к, _ in ПУНКТЫ)


def не_отмечено(отметки) -> list:
    """Отметки диагностики из бота → пункты без ответа, короткими надписями."""
    d = отметки if isinstance(отметки, dict) else {}
    if d.get(ЗАПЕЧАТАН):
        return []
    return [к for k, к, _ in ПУНКТЫ if not isinstance(d.get(k), bool)]


def чего_нет(состояние) -> list:
    """Состояние приёма медиа (ответ сервера) → чего ещё не хватает, словами.

    Пустой список — фото, видео и диагностика собраны, сделку можно отправлять. Этим же
    списком программа объясняет, почему кнопка «Отправить в Оценку» пока не нажимается:
    «не хватает» без перечисления заставляет сотрудника гадать, а телефон клиента лежит
    на столе.
    """
    с = состояние if isinstance(состояние, dict) else {}
    нет = []
    фото = int(с.get("фото") or 0)
    if фото < НУЖНО_ФОТО:
        нет.append(f"фото: {фото} из {НУЖНО_ФОТО}")
    if not с.get("видео"):
        нет.append("видео телефона")
    осталось = list(с.get("не_отмечено") or [])
    if осталось:
        хвост = f" и ещё {len(осталось) - 3}" if len(осталось) > 3 else ""
        нет.append("диагностика: " + ", ".join(осталось[:3]) + хвост)
    return нет


def ссылка_теста(ip: str, порт: int, токен: str) -> str:
    """Адрес страницы теста на телефоне клиента (мини-сервер в самом киоске).
    Отдельно от ссылки на бота: это другая сеть и другой получатель."""
    return f"http://{ip}:{int(порт)}/t/{токен}" if ip and токен else ""
